// Checks for punycode, base58, roman-numerals, dotted-path, template-render, ini-parse, pii-mask,
// password-generate and html-escape. Vector literals are generated by a script from the shared wave 11 vectors.json
// (hex strings are byte inputs). Strings are compared as Unicode scalars because Swift String equality treats
// canonically equivalent text as equal.
import GenlibSwift

private func scalars(_ s: String) -> [UInt32] { s.unicodeScalars.map(\.value) }
private func same(_ c: inout Checks, _ name: String, _ expected: String?, _ actual: () throws -> String?) {
    do {
        let v = try actual()
        let ok = v.map(scalars) == expected.map(scalars)
        if !ok { print("  expected <\(expected ?? "nil")> got <\(v ?? "nil")>") }
        c.check(name, ok)
    } catch {
        print("  unexpected error: \(error)")
        c.check(name, false)
    }
}
private func hexOf(_ b: [UInt8]) -> String { b.map { String($0, radix: 16).count == 1 ? "0" + String($0, radix: 16) : String($0, radix: 16) }.joined() }
private func hex(_ h: String) -> [UInt8] {
    let a = Array(h.utf8)
    return stride(from: 0, to: a.count, by: 2).map { UInt8(String(decoding: a[$0..<$0 + 2], as: UTF8.self), radix: 16)! }
}
private func json(_ text: String) -> JsonPatch.Value {
    do { return try JsonPatch.parse(text) } catch { fatalError("bad test JSON \(text): \(error)") }
}
/// Deterministic test byte source: cycles through the given bytes (passgen_ref.byte_source).
private func byteSource(_ h: String) -> () -> UInt8 {
    let b = hex(h)
    var i = 0
    return { defer { i += 1 }; return b[i % b.count] }
}
private func iniKey(_ doc: IniParse.Document) -> String {
    doc.map { s in s.name + "\u{241D}" + s.entries.map { "\($0.key)\u{241F}\($0.value)" }.joined(separator: "\u{241E}") }
        .joined(separator: "\u{241C}")
}

func runWave11Checks(_ c: inout Checks) {
