    same(&c, "punycode encode 9", "a-b-") { try Punycode.encode("a-b") }
    same(&c, "punycode encode 10", "--") { try Punycode.encode("-") }
    same(&c, "punycode encode 11", "mgbmm8erar") { try Punycode.encode("الحريه") }
    same(&c, "punycode encode 12", "Hello-Another-Way--fc4qua05auwb3674vfr0b") { try Punycode.encode("Hello-Another-Way-それぞれの場所") }
    same(&c, "punycode encode 13", "BER-ska") { try Punycode.encode("ÜBER") }
    same(&c, "punycode encode 14", "x-bga22n") { try Punycode.encode("xé́") }
    same(&c, "punycode decode 0", "bücher") { try Punycode.decode("bcher-kva") }
    same(&c, "punycode decode 1", "münchen") { try Punycode.decode("mnchen-3ya") }
    same(&c, "punycode decode 2", "日本語") { try Punycode.decode("wgv71a119e") }
    same(&c, "punycode decode 3", "ü") { try Punycode.decode("tda") }
    same(&c, "punycode decode 4", "abc") { try Punycode.decode("abc-") }
    same(&c, "punycode decode 5", "Mañana") { try Punycode.decode("Maana-pta") }
    same(&c, "punycode decode 6", "ελληνικά") { try Punycode.decode("hxargifdar") }
    same(&c, "punycode decode 7", "правда") { try Punycode.decode("80aafi6cg") }
    same(&c, "punycode decode 8", "😀") { try Punycode.decode("e28h") }
    same(&c, "punycode decode 9", "a-b") { try Punycode.decode("a-b-") }
    same(&c, "punycode decode 10", "-") { try Punycode.decode("--") }
    same(&c, "punycode decode 11", "الحريه") { try Punycode.decode("mgbmm8erar") }
    same(&c, "punycode decode 12", "Hello-Another-Way-それぞれの場所") { try Punycode.decode("Hello-Another-Way--fc4qua05auwb3674vfr0b") }
    same(&c, "punycode decode 13", "ÜBER") { try Punycode.decode("BER-ska") }
    same(&c, "punycode decode 14", "xé́") { try Punycode.decode("x-bga22n") }
    same(&c, "punycode decode 15", "bücher") { try Punycode.decode("bcher-kva") }
