    same(&c, "punycode domainToAscii 1", "example.com") { try Punycode.domainToAscii("EXAMPLE.com") }
    same(&c, "punycode domainToAscii 2", "xn--wgv71a119e.jp.") { try Punycode.domainToAscii("日本語.jp.") }
    same(&c, "punycode domainToAscii 3", "xn--mnchen-3ya.de") { try Punycode.domainToAscii("münchen.de") }
    same(&c, "punycode domainToAscii 4", "a.b.c") { try Punycode.domainToAscii("a.b.c") }
