    c.throwsError("punycode invalid decode 0", { _ = try Punycode.decode("bcher-kv!") }, where: { $0 is PunycodeError })
    c.throwsError("punycode invalid decode 1", { _ = try Punycode.decode("a-99999999999999999999") }, where: { $0 is PunycodeError })
