    c.throwsError("base58 invalid check 1", { _ = try Base58.checkDecode("1") }, where: { $0 is Base58Error })
    c.throwsError("base58 invalid check 2", { _ = try Base58.checkDecode("") }, where: { $0 is Base58Error })
    c.eq("roman to 1", "I", try RomanNumerals.toRoman(1))
    c.eq("roman to 4", "IV", try RomanNumerals.toRoman(4))
    c.eq("roman to 9", "IX", try RomanNumerals.toRoman(9))
